"""Lossless review-density pack; no approved originals or receipts are edited."""
from pathlib import Path
from PIL import Image,ImageChops
import json,hashlib
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public/assets/botuo-basic-packing-v1';OUT.mkdir(exist_ok=True)
SRC=ROOT/'docs/art/candidates/botuo/basic/composite-review-v1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return Image.open(p).convert('RGBA')
def record(source,output,**extra):
 im=read(output)
 return dict(source=str(source.relative_to(ROOT)),sourceSha256=sha(source),output=str(output.relative_to(ROOT)),sha256=sha(output),width=im.width,height=im.height,encodedBytes=output.stat().st_size,decodedBytes=im.width*im.height*4,**extra)
files=[];mapping={};saved=0
# Idle F1 was superseded by the original approved static source after the
# player's scale report. Never rebind that retired derivative on regeneration.
active_legacy=[c for c in json.loads((ROOT/'docs/verification/P2_BASIC_PACKING_INPUTS.json').read_text()) if c['asset']['key']!='botuo.battleIdle']
for c in active_legacy:
 a=c['asset'];d=c['oldDescriptor'];top=c['top'];height=c['height'];source=ROOT/'public'/a['path'];assert sha(source)==c['sourceSha256'];im=read(source)
 oldh=d['frames'][0]['height'];assert im.height%oldh==0
 packed=Image.new('RGBA',(im.width,im.height//oldh*height));restored=Image.new('RGBA',im.size)
 for row in range(im.height//oldh):
  crop=im.crop((0,row*oldh+top,im.width,row*oldh+top+height));packed.paste(crop,(0,row*height));restored.paste(crop,(0,row*oldh+top))
 assert restored.tobytes()==im.tobytes(),a['key']
 output=OUT/(a['key'].replace('.','-')+'.png');packed.save(output)
 files.append(record(source,output,kind='legacy',packedHeight=height,**{k:c[k] for k in ['character','slot','oldDescriptor','top']}))
 mapping[a['key']]=dict(top=top,height=height,oldHeight=oldh)
 saved+=(im.width*im.height-packed.width*packed.height)*4
# One existing P1 FX derivative: exact blank rows only, original remains immutable.
source=ROOT/'public/assets/characters/lushu/awakening-runtime-v1/C-source.png'
im=read(source);crop=im.crop((0,36,93,62));restored=Image.new('RGBA',im.size);restored.paste(crop,(0,36));assert restored.tobytes()==im.tobytes()
output=OUT/'lushu-awakeningCSource.png';crop.save(output)
files.append(record(source,output,kind='legacy-effect',top=36,oldHeight=96))
saved+=(96-26)*93*4
strip=Image.new('RGBA',(632,143));poseCells=[]
for i,n in enumerate(['F1','F2','F3','F4']):
 source=SRC/(n+'-safe-cell.png');im=read(source);cell=im.crop((100,148,258,291))
 restored=Image.new('RGBA',im.size);restored.paste(cell,(100,148));assert restored.tobytes()==im.tobytes()
 strip.paste(cell,(i*158,0));poseCells.append(dict(source=str(source.relative_to(ROOT)),sha256=sha(source),index=i))
poses=OUT/'botuo-basicPoses.png';strip.save(poses)
new=[dict(key='botuo.basicPoses',path=str(poses.relative_to(ROOT/'public')),width=632,height=143,bytes=poses.stat().st_size)]
for name,size,box,key in [('source-force-raw-v1.png',(180,134),(22,9,168,123),'botuo.basicSource'),('target-impact-raw-v1.png',(142,126),(19,4,124,119),'botuo.basicContact')]:
 source=SRC/name;im=read(source).resize(size,Image.Resampling.LANCZOS);crop=im.crop(box)
 restored=Image.new('RGBA',im.size);restored.paste(crop,box[:2]);assert restored.tobytes()==im.tobytes()
 output=OUT/(key.replace('.','-')+'.png');crop.save(output)
 files.append(record(source,output,kind='effect',reviewSize=size,crop=box,reviewRgbaReconstructionExact=True))
 new.append(dict(key=key,path=str(output.relative_to(ROOT/'public')),width=crop.width,height=crop.height,bytes=output.stat().st_size))
report=dict(status='SOURCE-PRESERVING PACK VERIFIED / see M5C_P2_BOTUO_BASIC_RUNTIME.md for integration gate',sourceCheckpoint='d40abb0e4b19a7b6471387934167df6b95334194',files=files,poseCells=poseCells,poses=str(poses.relative_to(ROOT)),newAssets=new,savedDecodedBytes=saved,additionDecodedBytes=sum(a['width']*a['height']*4 for a in new),policy='Exact accepted safe-cell RGBA without further resize; effects use exact accepted full-canvas review resize then zero-RGBA crop. Legacy per-frame blank rows only; retain originals and origin. One P1 C-source lossless blank-row derivative; no pose/timing or accepted art changes.')
(ROOT/'docs/verification/P2_BASIC_RUNTIME_ASSETS.json').write_text(json.dumps(report,indent=2)+'\n')
(ROOT/'src/assets/runtimePacking.js').write_text('// Generated by prepareBotuoBasicRuntime.py; exact blank rows, no source edits.\nexport const runtimeRowPacking='+json.dumps(mapping,indent=2)+';\nexport const runtimeEffectRowPacking={"lushu.awakeningCSource":{top:36,oldHeight:96,height:26}};\nexport function repackActionEffectRows(input){const pack=e=>{const p=runtimeEffectRowPacking[e.assetKey];return p?{...e,offset:[e.offset[0],e.offset[1]+e.size[1]*p.top/p.oldHeight],size:[e.size[0],e.size[1]*p.height/p.oldHeight]}:e;};return input.kind==="staged"?{...input,stages:input.stages.map(s=>({...s,blade:pack(s.blade),contact:pack(s.contact)}))}:{...input,blade:pack(input.blade),contact:pack(input.contact)};}\nexport function repackAnimationRows(input){\n const p=runtimeRowPacking[input.source];if(!p)return input;\n const w=input.frames[0].width;\n return {...input,frames:input.frames.map(f=>({...f,y:f.y/p.oldHeight*p.height,height:p.height})),origin:[input.origin[0],(input.origin[1]*p.oldHeight-p.top)/p.height],scale:input.scale*Math.max(w,p.height)/Math.max(w,p.oldHeight)};\n}\n')
manifest=ROOT/'src/assets/manifest.js';text=manifest.read_text()
import re
for a in new:
 entry="{key:'%s',type:'image',path:'%s',width:%d,height:%d,bytes:%d,fallback:'%s'}"%(a['key'],a['path'],a['width'],a['height'],a['bytes'],'placeholder.battle' if a['key'].endswith('Poses') else 'placeholder.vfx')
 pattern=r"\{key:'"+re.escape(a['key'])+r"',type:'image',path:'[^']+',width:\d+,height:\d+,bytes:\d+,fallback:'[^']+'\}"
 if re.search(pattern,text):text=re.sub(pattern,lambda _:entry,text)
 else:text=text.replace('const entries=[','const entries=[\n '+entry+',')
for f,c in zip(files,active_legacy):
 if f['kind']!='legacy':continue
 key=c['asset']['key'];replacement="{key:'%s',type:'image',path:'%s',width:%d,height:%d,bytes:%d,fallback:'placeholder.battle'}"%(key,str(Path(f['output']).relative_to('public')),f['width'],f['height'],f['encodedBytes'])
 text=re.sub(r"\{key:'"+re.escape(key)+r"',type:'image',path:'[^']+',width:\d+,height:\d+,bytes:\d+,fallback:'[^']+'\}",lambda _:replacement,text)
f=next(f for f in files if f['kind']=='legacy-effect')
text=re.sub(r"\{key:'lushu.awakeningCSource',type:'image',path:'[^']+',width:\d+,height:\d+,bytes:\d+,fallback:'[^']+'\}",lambda _:"{key:'lushu.awakeningCSource',type:'image',path:'assets/botuo-basic-packing-v1/lushu-awakeningCSource.png',width:93,height:26,bytes:%d,fallback:'placeholder.vfx'}"%f['encodedBytes'],text)
manifest.write_text(text)
print(json.dumps({k:report[k] for k in ['savedDecodedBytes','additionDecodedBytes']}))
